          "Αρνητικές μεταβολές σε γνωστικό επίπεδο και διάθεση: Αδυναμία ανάκλησης κρίσιμων σημείων του τραύματος, επίμονα διογκωμένες αρνητικές πεποιθήσεις για τον εαυτό ή τον κόσμο, διαστρεβλωμένη αυτοκατηγορία/ενοχή, ανηδονία και συναισθηματικό μούδιασμα.",
          "Μεταβολές στην εγρήγορση και αντιδραστικότητα: Ευερεθιστότητα, εκρήξεις θυμού, υπερεπαγρύπνηση, υπερβολική αντίδραση ξαφνιάσματος (startle response), δυσκολία συγκέντρωσης και διαταραχές ύπνου."
