          "Προμετωπιαίος φλοιός (vmPFC / πρόσθιος προσαγώγιος ACC): Μειωμένη λειτουργία και αποτυχία επιτελικής αναστολής της αμυγδαλής (ανεπαρκής απόσβεση φόβου).",
          "Ιππόκαμπος: Μειωμένος όγκος ιπποκάμπου και διαταραχή της συμφραστικής επεξεργασίας του τραύματος."
