          "Θεραπευτικό χάσμα (Therapeutic latency): Ενώ η συναπτική αύξηση των μονοαμινών συμβαίνει εντός ωρών, η κλινική αντικαταθλιπτική δράση απαιτεί 2 έως 4 εβδομάδες.",
