          "Μέτρια έως σοβαρή κατάθλιψη: Συνδυασμός αντικαταθλιπτικής αγωγής (SSRIs πρώτης γραμμής: σερτραλίνη, εσιταλοπράμη, σιταλοπράμη) με ατομική ψυχοθεραπεία (CBT ή Διαπροσωπική Θεραπεία - IPT).",
          "Σοβαρή κατάθλιψη με ψυχωσικά στοιχεία: Συνδυασμός αντικαταθλιπτικού με άτυπο αντιψυχωσικό, ή Ηλεκτροσπασμοθεραπεία (ECT).",
          "Συνέχιση αγωγής: Τουλάχιστον 6-9 μήνες μετά την πλήρη ύφεση ενός μεμονωμένου επεισοδίου· τουλάχιστον 2 έτη σε υποτροπιάζουσα κατάθλιψη."
