          "4. Αλλαγή κατηγορίας: Μετάβαση σε SNRI (βενλαφαξίνη, ντουλοξετίνη), τρικυκλικό (TCAs) ή αναστολέα ΜΑΟ (MAOIs).",
          "5. Νεότερες παρεμβάσεις: Ενδορρινική εσκεταμίνη, ενδοφλέβια κεταμίνη, rTMS ή ECT."
