          "Eugen Bleuler (1911): Εισήγαγε τον όρο «Σχιζοφρένεια» (σχίζειν + φρήν), τονίζοντας τη διάσπαση των ψυχικών λειτουργιών. Περιέγραψε τα 4 θεμελιώδη συμπτώματα (τα 4 Α): Διαταραχή Συνειρμών (Associations), Αμβλύ Συναίσθημα (Affect), Αυτισμός (Autism), Αμφιθυμία (Ambivalence).",
          "Kurt Schneider (1959): Περιέγραψε τα συμπτώματα πρώτης τάξης (First-Rank Symptoms)."
