          "Fromm-Reichmann (1948): Η έννοια της «σχιζοφρενογόνου μητέρας» (απορριπτική, ψυχρή και ταυτόχρονα υπερπροστατευτική μητέρα) — πλήρως καταρριφθείσα από τη σύγχρονη επιστήμη.",
          "Bateson (1956): Η θεωρία του «διπλού δεσμού» (Double-bind theory) — αντιφατικά επικοινωνιακά μηνύματα από τους γονείς που παγιδεύουν το παιδί.",
          "Σύγχρονη τεκμηριωμένη προσέγγιση: Το οικογενειακό περιβάλλον ΔΕΝ προκαλεί τη σχιζοφρένεια. Ωστόσο, το Υψηλό Εκφραζόμενο Συναίσθημα (High Expressed Emotion - κριτική, εχθρότητα, συναισθηματική υπερεμπλοκή) αποτελεί ισχυρό παράγοντα κινδύνου για ΥΠΟΤΡΟΠΗ, δικαιολογώντας τη σημασία των οικογενειακών παρεμβάσεων."
