          "Αυτοάνοσο μοντέλο: Η anti-NMDAR εγκεφαλίτιδα εκδηλώνεται αρχικά με τυπική ψύχωση, υποστηρίζοντας τον κεντρικό ρόλο των υποδοχέων NMDA."
