          "Σχήμα φόρτισης: Η παλιπεριδόνη LAI (Xeplion) χρησιμοποιεί σχήμα ταχείας φόρτισης στον δελτοειδή (150 mg την 1η ημέρα, 100 mg την 8η ημέρα) χωρίς ανάγκη από του στόματος επικάλυψης."
