          "Ιδέες αναφοράς (Ideas of reference): Η υποψία ότι τυχαία εξωτερικά γεγονότα, λόγια ή άρθρα αναφέρονται στο άτομο, με διατηρημένη όμως κάποια αμφιβολία.",
