          "Παραληρητικές ιδέες δίωξης: Ακλόνητη πεποίθηση ότι συγκεκριμένα πρόσωπα ή οργανώσεις συνωμοτούν, παρακολουθούν ή προσπαθούν να βλάψουν τον ασθενή.",
          "Υπερτιμημένες ιδέες (Overvalued ideas): Έντονες, συναισθηματικά φορτισμένες πεποιθήσεις που δεσπόζουν στη ζωή του ατόμου χωρίς να έχουν αυστηρά παραληρητικό χαρακτήρα."
