          "D. Εάν έχουν εκδηλωθεί επεισόδια διάθεσης (μανιακά ή καταθλιπτικά), η συνολική διάρκειά τους είναι σύντομη σε σύγκριση με τη διάρκεια των παραληρητικών περιόδων.",
          "Ε. Αποκλεισμός χρήσης ουσιών, φαρμάκων ή υποκείμενης σωματικής/νευρολογικής νόσου."
