          "Φαρμακοθεραπεία: Δεν υπάρχει εγκεκριμένη πρωτοπαθής φαρμακοθεραπεία. Χαμηλή δόση ολανζαπίνης μπορεί να βοηθήσει στη μείωση του έντονου άγχους γύρω από το φαγητό και του ιδεοληπτικού βάρους."
