          "Φαρμακοθεραπεία: Προορίζεται ΜΟΝΟ για βραχυχρόνια χρήση (έως 2-4 εβδομάδες) σε οξεία, σοβαρή δυσφορία.",
          "Επιλογές: Μη βενζοδιαζεπινικά υπναγωγά Z-drugs (ζοπικλόνη, ζολπιδέμη), βραχείας δράσης βενζοδιαζεπίνες, μελατονίνη παρατεταμένης αποδέσμευσης, δαριδορεξάντη (ανταγωνιστής ορεξίνης) ή χαμηλή δόση κατασταλτικών αντικαταθλιπτικών (τραζοδόνη, μιρταζαπίνη)."
