          "Φαρμακογενή αίτια: Κατασταλτικά φάρμακα, αντιψυχωσικά, αντικαταθλιπτικά, αντιισταμινικά, βενζοδιαζεπίνες.",
          "Ιδιοπαθής υπερυπνία και ιατρικές παθήσεις (υποθυρεοειδισμός, εγκεφαλίτιδα, κρανιοεγκεφαλικό τραύμα)."
