          "Λειτουργική απεικόνιση: SPECT DatSCAN (έλλειμμα ντοπαμινεργικών μεταφορέων σε άνοια με σωμάτια Lewy), FDG-PET (υπομεταβολισμός βρεγματοκροταφικά σε Alzheimer, μετωποκροταφικά σε FTD)."
