      {
        "type": "section",
        "heading": "Αυτοσωμικές επικρατείς μεταλλάξεις (<1-2% των περιπτώσεων, έναρξη <60 ετών)",
        "items": [
          "Γονίδιο APP (Amyloid Precursor Protein) στο χρωμόσωμα 21: Μεταλλάξεις οδηγούν σε αυξημένη παραγωγή του τοξικού πεπτιδίου Aβ42 (εξηγεί την καθολική εμφάνιση Alzheimer στα άτομα με σύνδρομο Down/τρισωμία 21).",
          "Γονίδιο PSEN1 (Presenilin 1) στο χρωμόσωμα 14: Συχνότερη αιτία πρώιμης οικογενούς νόσου (εξαιρετικά πρώιμη έναρξη, συχνά 35-50 ετών). Συστατικό της γ-σεκρετάσης.",
          "Γονίδιο PSEN2 (Presenilin 2) στο χρωμόσωμα 1: Σπανιότερες μεταλλάξεις της γ-σεκρετάσης.",
          "Σημείωση: Στην όψιμη σποραδική μορφή (>65 ετών), ο σημαντικότερος γενετικός παράγοντας κινδύνου είναι το αλληλόμορφο ε4 του γονιδίου APOE (Απολιποπρωτεΐνη Ε) στο χρωμόσωμα 19 (αυξάνει τον κίνδυνο κατά 3 φορές στους ετεροζυγώτες και 12-15 φορές στους ομοζυγώτες)."
        ]
      }
