          "Άνοια με Σωμάτια Lewy (Dementia with Lewy Bodies - DLB): Η άνοια προηγείται ή εμφανίζεται ταυτόχρονα με τα παρκινσονικά συμπτώματα (ή εντός 1 έτους από την έναρξη του παρκινσονισμού - «κανόνας 1 έτους»).",
          "Άνοια στη Νόσο Parkinson (Parkinson's Disease Dementia - PDD): Η άνοια αναπτύσσεται στο πλαίσιο καλά εγκατεστημένης νόσου Parkinson (παρκινσονισμός για περισσότερο από 1 έτος πριν από την εμφάνιση άνοιας).",
