          "Πρωτοπαθής Προϊούσα Αφασία - Σημασιολογική παραλλαγή / Σημασιολογική Άνοια (svPPA): Κυριαρχεί η απώλεια της σημασίας των λέξεων και της εννοιολογικής γνώσης (βλάβη πρόσθιου κροταφικού λοβού).",
          "Συσχέτιση με Νόσο Κινητικού Νευρώνα (FTD-MND / ALS): Μετάλλαξη C9orf72."
