          "Υπερστοματικότητα και διατροφικές αλλαγές (έντονη προτίμηση για γλυκά/υδατάνθρακες, βουλιμική κατανάλωση, στοματική εξερεύνηση μη βρώσιμων αντικειμένων).",
          "Εκτελεστικό νευροψυχολογικό έλλειμμα με σχετική διατήρηση της επεισοδιακής μνήμης και των χωροταξικών λειτουργιών στα πρώιμα στάδια."
