        "type": "section",
        "heading": "Δείκτες μετάβασης σε ολοκληρωμένη αυτοκτονία",
        "items": [
          "Μεγαλύτερη ηλικία (>45-50 ετών).",
          "Ανδρικό φύλο.",
          "Χρήση υψηλής επικινδυνότητας/θανατηφόρας μεθόδου στην προηγούμενη απόπειρα.",
          "Σοβαρή συνυπάρχουσα μείζων κατάθλιψη, διπολική διαταραχή ή ψύχωση.",
          "Επίμονη, βαθιά απελπισία και μεταμέλεια για το γεγονός ότι επέζησε της απόπειρας.",
          "Κακή σωματική υγεία και μοναχική διαβίωση.",
          "Περίοδος αμέσως μετά το εξιτήριο από ψυχιατρική νοσηλεία (ιδίως οι πρώτες 30 ημέρες)."
        ]
