          "Λήψη ενεργών μέτρων αποφυγής ανακάλυψης ή διάσωσης (π.χ. κλειδωμένη πόρτα, απόμερο μέρος, επιλογή ώρας που λείπουν όλοι).",
          "Διευθέτηση τελικών εκκρεμοτήτων (σύνταξη διαθήκης, τακτοποίηση οικονομικών, αποχαιρετιστήρια δώρα).",
