          "Ολοκληρωμένη ψυχιατρική και ψυχοκοινωνική εκτίμηση πριν από την έξοδο από το νοσοκομείο.",
          "Σύνταξη συνεργατικού σχεδίου ασφάλειας (Safety plan) και διαχείρισης κρίσεων.",
          "Ταχεία διασύνδεση με εξωνοσοκομειακή φροντίδα (ραντεβού παρακολούθησης εντός 48-72 ωρών από το εξιτήριο).",
          "Εμπλοκή της οικογένειας και των υποστηρικτικών προσώπων με τη συγκατάθεση του ασθενούς."
