          "Νευρολογικές παθήσεις: Σκλήρυνση κατά πλάκας, νόσος Parkinson, επιληψία, εγκεφαλικοί όγκοι, αγγειακά εγκεφαλικά επεισόδια.",
          "Αυτοάνοσες νόσοι: Συστηματικός ερυθηματώδης λύκος (ΣΕΛ - νευροψυχιατρικός λύκος), anti-NMDAR εγκεφαλίτιδα.",
          "Λοιμώξεις: Εγκεφαλίτιδα HSV, σύφιλη ΚΝΣ, HIV, νόσος Lyme.",
          "Μεταβολικές διαταραχές: Νόσος Wilson, οξεία διαλείπουσα πορφυρία, έλλειψη βιταμίνης Β12."
