          "3. Αυτόνομη υπερδραστηριότητα: Υπερπυρεξία, εφίδρωση, ταχυκαρδία, ταχύπνοια, διακυμάνσεις αρτηριακής πίεσης, μυδρίαση, υπερδραστήριοι εντερικοί ήχοι/διάρροια.",
          "Διαφορική διάγνωση από NMS: Το Σύνδρομο Σεροτονίνης έχει οξεία έναρξη (εντός 24 ωρών), κυριαρχούν ο κλόνος, η υπερρεφλεξία και η διάρροια (έναντι της βραδείας έναρξης, της «μολυβδοσωλήνας» δυσκαμψίας και της υπορεφλεξίας στο NMS).",
