        "items": [
          "Πρόσθια καψουλοτομή (Anterior capsulotomy): Καταστροφή του πρόσθιου σκέλους της έσω κάψας (χρησιμοποιείται κυρίως σε ανθεκτική ΙΨΔ).",
          "Πρόσθια προσαγωγιοτομή (Anterior cingulotomy): Καταστροφή της πρόσθιας έλικας του προσαγωγίου (χρησιμοποιείται σε ανθεκτική κατάθλιψη και ΙΨΔ).",
          "Υποκερατοειδής διατομή (Subcaudate tractotomy): Διατομή των ινών κάτω από την κεφαλή του κερκοφόρου πυρήνα.",
          "Μεταιχμιακή λευκοτομή (Limbic leucotomy): Συνδυασμός προσαγωγιοτομής και υποκερατοειδούς διατομής.",
          "Εν τω βάθει εγκεφαλική διέγερση (DBS - Deep Brain Stimulation): Αναστρέψιμη ηλεκτρική διέγερση (χωρίς καταστροφή ιστού) στο πρόσθιο σκέλος έσω κάψας / κοιλιακό ραβδωτό (VC/VS) ή στην υπογονατιαία περιοχή (Brodmann area 25)."
        ]
